window.AUTH=window.AUTH||{};window.AUTH["16-9493"]={"d":"16-9493","id":"2017/16-9493","n":"Rosales-Mireles v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Rosales-Mireles, Florencio","date":"2017-11-29","url":"https://www.supremecourt.gov/DocketPDF/16/16-9493/22031/20171129175612614_16-9493ts.pdf","side":"pet","n":44},{"k":"respondent","label":"Brief of respondent United States","date":"2018-01-10","url":"https://www.supremecourt.gov/DocketPDF/16/16-9493/27456/20180110180947765_16-9493bsUnitedStates.pdf","side":"res","n":68},{"k":"reply","label":"Reply of petitioner Rosales-Mireles, Florencio","date":"2018-02-09","url":"https://www.supremecourt.gov/DocketPDF/16/16-9493/34984/20180209131848728_16-9493%20Reply%20Brief.pdf","side":"pet","n":17}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Argersinger v. Hamlin","cite":"407 U.S. 25","y":1972,"id":"1971/70-5015","sc":1,"sum":"In Gideon v. Wainwright (1963) the Court found that the Sixth and Fourteenth Amendments required states to provide an attorney to indigent defendants in cases involving serious crimes. In this case, a unanimous Court extended that right to cover defendants charged with misdemeanors who faced the possibility of a jail sentence.","sumSrc":"Oyez","by":{"0":"11","1":"28"}},{"t":"case","label":"Baldwin v. New York","cite":"399 U.S. 66","y":1970,"id":"1969/188","sc":1,"sum":"The judgment is reversed. Pp. 6776. 24 N. Y. 2d 207, 247 N. E. 2d 260, reversed. MR. JUSTICE WHITE, joined by MR. JUSTICE BRENNAN and MR. JUSTICE MARSHALL, concluded that defendants accused of serious crimes must, under the Sixth Amendment, as made applicable to the States by the Fourteenth Amendment, be afforded the right to trial by jury, Duncan v. Louisiana, 391 U. S. 145, and though \"petty crimes\" may be tried …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Barber v. Thomas","cite":"130 S. Ct. 2499","y":2010,"id":"2009/09-5201","sc":1,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Breithaupt v. Abram","cite":"352 U.S. 432","y":1957,"id":"1956/69","sc":1,"sum":"Petitioner was not deprived of due process of law in violation of the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Cty. of Sacramento v. Lewis","cite":"523 U.S. 833","y":1998,"id":"1997/96-1337","sc":1,"sum":"In a unanimous decision the Court first ruled that the Fourth Amendment's reasonableness standards prevented its illegal seizure protections from applying to high-speed police chases. Such incidents are merely pursuits and do not constitute actual seizures, especially if they fail due to the death of the subject.","sumSrc":"Oyez","by":{"0":"7, 8, 19, 20","1":"34"}},{"t":"case","label":"Daniels v. Williams","cite":"474 U.S. 327","y":1986,"id":"1985/84-5872","sc":1,"sum":"The Due Process Clause is not implicated by a state official's negligent act causing unintended loss of or injury to life, liberty, or property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 20"}},{"t":"case","label":"Foucha v. Louisiana","cite":"504 U.S. 71","y":1992,"id":"1991/90-5844","sc":1,"sum":"The judgment is reversed. 563 So. 2d 1138, reversed. JUSTICE WHITE delivered the opinion of the Court with respect to Parts I and II, concluding that the Louisiana statute violates the Due Process Clause because it allows an insanity acquittee to be committed to a mental institution until he is able to demonstrate that he is not dangerous to himself and others, even though he does not suffer from any mental illness. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Gall v. United States","cite":"552 U.S. 38","y":2007,"id":"2007/06-7949","sc":1,"sum":"The Supreme Court, in a 7-2 ruling, reversed the appellate court and held that, under Booker , federal courts have the authority to set any reasonable sentence as long as they explain their reasoning. The Court made clear that Booker had removed the Guidelines from their earlier status as the primary determinate of a defendant's punishment, reaffirming the Guidelines' advisory status.","sumSrc":"Oyez","by":{"0":"6, 12","1":"2, 20","2":"7, 13"}},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"0":"11, 22","2":"13"}},{"t":"case","label":"Henderson v. United States","cite":"568 U.S. 266","y":2013,"id":"2012/11-9307","sc":1,"sum":"The Court held that the determination of “plain error” is made during the appellate review, not during the trial.","sumSrc":"Oyez","by":{"0":"21","1":"19, 26","2":"10"}},{"t":"case","label":"Hicks v. United States","cite":"137 S. Ct. 2000","y":2017,"url":"https://www.courtlistener.com/c/S.%20Ct./137/2000/","sc":1,"by":{"0":"1, 2, 3, 10, 11","2":"7"}},{"t":"case","label":"Johnson v. United States","cite":"520 U.S. 461","y":1997,"id":"1996/96-203","sc":1,"sum":"The Court held that the trial court's action in this case was not \"plain error\" of the sort which an appellate court may notice under Federal Rule of Criminal Procedure 52(b).","sumSrc":"Oyez","by":{"0":"9, 10","1":"16, 17, 29"}},{"t":"case","label":"Molina-Martinez v. United States","cite":"136 S. Ct. 1338","y":2016,"id":"2015/14-8913","sc":1,"ar":8,"sum":"The Court held that an error in the application of the U.S. Sentencing Guidelines that results in the wrong Guideline range affected the defendant’s substantial rights.","sumSrc":"Oyez","by":{"0":"passim","1":"3, 19, 21, 23, 25, 26","2":"passim"}},{"t":"case","label":"Peugh v. United States","cite":"133 S. Ct. 2072","y":2013,"id":"2012/12-62","sc":1,"ar":1,"sum":"The Court found that using the U.S. Sentencing Guidelines at the time of the sentencing for a crime rather than at the time of the offense is a violation of the ex post facto clause.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Puckett v. United States","cite":"556 U.S. 129","y":2009,"id":"2008/07-9712","sc":1,"sum":"The Court found that the \"plain error standard\" of Rule 52(b) of the Federal Rules of Criminal Procedure governs if claims forfeited at trial may be raised at the appellate level.","sumSrc":"Oyez","by":{"0":"7, 10, 17","1":"passim","2":"7"}},{"t":"case","label":"Rita v. United States","cite":"551 U.S. 338","y":2007,"id":"2006/06-5754","sc":1,"ar":1,"sum":"The Court ruled that courts of appeals may apply a nonbinding presumption of reasonableness to within-Guidelines sentences. Justice Stephen Breyer wrote the opinion for the 8-1 majority.","sumSrc":"Oyez","by":{"0":"14, 15, 22","1":"2, 21, 30, 31"}},{"t":"case","label":"Rochin v. California","cite":"342 U.S. 165","y":1952,"id":"1940-1955/342us165","sc":1,"sum":"The Court reversed the conviction. The police violated Rochin's right to due process of law. Due process was an admittedly vague concept, but it prohibited \"conduct that shocks the conscience.\" This nebulous approach was mocked in a concurring opinion by Justice Black.","sumSrc":"Oyez","by":{"0":"19, 20","1":"34"}},{"t":"case","label":"United States v. Booker","cite":"543 U.S. 220","y":2005,"id":"2004/04-104","sc":1,"ar":4,"sum":"The Court held that the Sentencing Guidelines, where they allow judges to enhance sentences using facts not reviewed by juries, violated the Sixth Amendment right to trial by jury. The sentences of Booker and Fanfan, based partly on facts determined only by judges, were therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"12","1":"31"}},{"t":"case","label":"United States v. Castillo-Casiano","cite":"198 F.3d 787","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/198/787/","by":{"0":"13, 15"}},{"t":"case","label":"United States v. Corso","cite":"549 F.3d 921","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/549/921/","by":{"0":"17","1":"24"}},{"t":"case","label":"United States v. Dahl","cite":"833 F.3d 345","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/833/345/","by":{"0":"16"}},{"t":"case","label":"United States v. Escalante-Reyes","cite":"689 F.3d 415","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/689/415/","by":{"0":"20","1":"9, 33"}},{"t":"case","label":"United States v. Figueroa-Ocasio","cite":"805 F.3d 360","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/805/360/","by":{"0":"16"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"sum":"In 1963, respondent was convicted of first-degree murder and sentenced to death by a jury in the Federal District Court for the District of Columbia, which at that time had exclusive jurisdiction over local felonies committed in the District. The Court of Appeals for the District of Columbia Circuit, which then acted as the local appellate court, upheld the conviction but set aside the death sentence, and respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"11, 14, 17, 25"}},{"t":"case","label":"United States v. Jaimes-Jaimes","cite":"406 F.3d 845","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/406/845/","by":{"0":"21"}},{"t":"case","label":"United States v. Langford","cite":"516 F.3d 205","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/516/205/","by":{"0":"14"}},{"t":"case","label":"United States v. Martinez-Rios","cite":"143 F.3d 662","y":1998,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/143/662/","by":{"0":"11"}},{"t":"case","label":"United States v. Olano","cite":"507 U.S. 725","y":1993,"id":"1992/91-1306","sc":1,"ar":5,"sum":"The presence of the alternate jurors during jury deliberations was not an error that the Court of Appeals was authorized to correct under Rule 52(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"passim","2":"2, 9"}},{"t":"case","label":"United States v. Pennington","cite":"667 F.3d 953","y":2012,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/953/","by":{"0":"11"}},{"t":"case","label":"United States v. Rushton","cite":"738 F.3d 854","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/738/854/","by":{"0":"22"}},{"t":"case","label":"United States v. Sabillon-Umana","cite":"772 F.3d 1328","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/772/1328/","ar":1,"by":{"0":"15, 16"}},{"t":"case","label":"United States v. Syme","cite":"276 F.3d 131","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/276/131/","by":{"0":"16"}},{"t":"case","label":"United States v. Wernick","cite":"691 F.3d 108","y":2012,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/691/108/","by":{"0":"16, 17"}},{"t":"case","label":"United States v. Westover","cite":"435 F.3d 1273","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/435/1273/","by":{"0":"18","1":"24, 25"}},{"t":"case","label":"Wall v. Kholi","cite":"562 U.S. 545","y":2011,"id":"2010/09-868","sc":1,"sum":"The Court held that the one-year window of time in which an inmate may file a habeas challenge to their sentence in federal court after conviction is delayed while a state court considers an inmate's request for a sentence reduction.","sumSrc":"Oyez","by":{"0":"9"}},{"t":"case","label":"Williams v. Pennsylvania","cite":"136 S. Ct. 1899","y":2016,"id":"2015/15-5040","sc":1,"sum":"The Court determined that the Eighth and Fourteenth Amendments are violated when a judge who was previously involved in the case as a prosecutor declines to recuse himself, regardless of whether that judge’s decision as part of a multi-member tribunal was dispositive.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Williams v. United States","cite":"503 U.S. 193","y":1992,"id":"1991/90-6297","sc":1,"sum":"Under the Sentencing Reform Act of 1984, the United States Sentencing Commission has promulgated Guidelines establishing sentencing ranges for different categories of federal offenses and defendants. The Act allows a district court to depart from a guideline range under certain circumstances, 18 U. S. C. §3553(b), and provides for limited appellate review of sentences, requiring a remand for resentencing if a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","2":"13"}},{"t":"usc","label":"18 U.S.C. § 3552","url":"https://www.law.cornell.edu/uscode/text/18/3552","subs":["(a)"],"stext":{"head":"§3552. Presentence reports","paras":[[0,"(a) Presentence Investigation and Report by Probation Officer.—A United States probation officer shall make a presentence investigation of a defendant that is required pursuant to the provisions of Rule 32(c) of the Federal Rules of Criminal Procedure, and shall, before the imposition of sentence, report the results of the investigation to the court."],[0,"(b) Presentence Study and Report by Bureau of Prisons.—If the court, before or after its receipt of a report specified in subsection (a) or (c), desires more information than is otherwise available to it as a basis for determining the sentence to be imposed on a defendant found guilty of a misdemeanor or felony, it may order a study of the defendant. The study shall be conducted in the local community by qualified consultants unless the sentencing judge finds that there is a compelling reason for the study to be done by the Bureau of Prisons or there are no adequate professional resources available in the local community to perform the study. The period of the study shall be no more than sixty days. The order shall specify the additional information that the court needs before determining the sentence to be imposed. Such an order shall be treated for administrative purposes as a provisional sentence of imprisonment for the maximum term authorized by section 3581(b) for the offense committed. The study shall inquire into such matters as are specified by the court and any other matters that the Bureau of Prisons or the professional consultants believe are pertinent to the factors set forth in section 3553(a). The period of the study may, in the discretion of the court, be extended for an additional period of not more than sixty days. By the expiration of the period of the study, or by the expiration of any extension granted by the court, the United States marshal shall, if the defendant is in custody, return the defendant to the court for final sentencing. The Bureau of Prisons or the professional consultants shall provide the court with a written report of the pertinent results of the study and make to the court whatever recommendations the Bureau or the consultants believe will be helpful to a proper resolution of the case. The report shall include recommendations of the Bureau or the consultants concerning the guidelines and policy statements, promulgated by the Sentencing Commission pursuant to 28 U.S.C. 994(a), that they believe are applicable to the defendant's case. After receiving the report and the recommendations, the court shall proceed finally to sentence the defendant in accordance with the sentencing alternatives and procedures available under this chapter."],[0,"(c) Presentence Examination and Report by Psychiatric or Psychological Examiners.—If the court, before or after its receipt of a report specified in subsection (a) or (b) desires more information than is otherwise available to it as a basis for determining the mental condition of the defendant, the court may order the same psychiatric or psychological examination and report thereon as may be ordered under section 4244(b) of this title."],[0,"(d) Disclosure of Presentence Reports.—The court shall assure that a report filed pursuant to this section is disclosed to the defendant, the counsel for the defendant, and the attorney for the Government at least ten days prior to the date set for sentencing, unless this minimum period is waived by the defendant. The court shall provide a copy of the presentence report to the attorney for the Government to use in collecting an assessment, criminal fine, forfeiture or restitution imposed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3552?type=usc&year=mostrecent&link-type=html"},"head":"§3552. Presentence reports","tname":"Crimes and Criminal Procedure","by":{"0":"12","1":"2, 2"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)","(a)(1)","(a)(5)","(c)"],"stext":{"head":"§3553. Imposition of a sentence","paras":[[0,"(a) Factors To Be Considered in Imposing a Sentence.—The court shall impose a sentence sufficient, but not greater than necessary, to comply with the purposes set forth in paragraph (2) of this subsection. The court, in determining the particular sentence to be imposed, shall consider—"],[1,"(1) the nature and circumstances of the offense and the history and characteristics of the defendant;"],[1,"(2) the need for the sentence imposed—"],[2,"(A) to reflect the seriousness of the offense, to promote respect for the law, and to provide just punishment for the offense;"],[2,"(B) to afford adequate deterrence to criminal conduct;"],[2,"(C) to protect the public from further crimes of the defendant; and"],[2,"(D) to provide the defendant with needed educational or vocational training, medical care, or other correctional treatment in the most effective manner;"],[1,"(3) the kinds of sentences available;"],[1,"(4) the kinds of sentence and the sentencing range established for—"],[2,"(A) the applicable category of offense committed by the applicable category of defendant as set forth in the guidelines—"],[3,"(i) issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, subject to any amendments made to such guidelines by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[3,"(ii) that, except as provided in section 3742(g), are in effect on the date the defendant is sentenced; or"],[2,"(B) in the case of a violation of probation or supervised release, the applicable guidelines or policy statements issued by the Sentencing Commission pursuant to section 994(a)(3) of title 28, United States Code, taking into account any amendments made to such guidelines or policy statements by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28);"],[1,"(5) any pertinent policy statement—"],[2,"(A) issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28, United States Code, subject to any amendments made to such policy statement by act of Congress (regardless of whether such amendments have yet to be incorporated by the Sentencing Commission into amendments issued under section 994(p) of title 28); and"],[2,"(B) that, except as provided in section 3742(g), is in effect on the date the defendant is sentenced.1"],[1,"(6) the need to avoid unwarranted sentence disparities among defendants with similar records who have been found guilty of similar conduct; and"],[1,"(7) the need to provide restitution to any victims of the offense."],[0,"(b) Application of Guidelines in Imposing a Sentence.—"],[1,"(1) In general.—Except as provided in paragraph (2), the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless the court finds that there exists an aggravating or mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence different from that described. In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission."],[1,"(2) Child crimes and sexual offenses.—"],[2,"(A) 2 Sentencing.—In sentencing a defendant convicted of an offense under section 1201 involving a minor victim, an offense under section 1591, or an offense under chapter 71, 109A, 110, or 117, the court shall impose a sentence of the kind, and within the range, referred to in subsection (a)(4) unless—"],[3,"(i) the court finds that there exists an aggravating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence greater than that described;"],[3,"(ii) the court finds that there exists a mitigating circumstance of a kind or to a degree, that—"],[4,"(I) has been affirmatively and specifically identified as a permissible ground of downward departure in the sentencing guidelines or policy statements issued under section 994(a) of title 28, taking account of any amendments to such sentencing guidelines or policy statements by Congress;"],[4,"(II) has not been taken into consideration by the Sentencing Commission in formulating the guidelines; and"],[4,"(III) should result in a sentence different from that described; or"],[3,"(iii) the court finds, on motion of the Government, that the defendant has provided substantial assistance in the investigation or prosecution of another person who has committed an offense and that this assistance established a mitigating circumstance of a kind, or to a degree, not adequately taken into consideration by the Sentencing Commission in formulating the guidelines that should result in a sentence lower than that described."],[0,"In determining whether a circumstance was adequately taken into consideration, the court shall consider only the sentencing guidelines, policy statements, and official commentary of the Sentencing Commission, together with any amendments thereto by act of Congress. In the absence of an applicable sentencing guideline, the court shall impose an appropriate sentence, having due regard for the purposes set forth in subsection (a)(2). In the absence of an applicable sentencing guideline in the case of an offense other than a petty offense, the court shall also have due regard for the relationship of the sentence imposed to sentences prescribed by guidelines applicable to similar offenses and offenders, and to the applicable policy statements of the Sentencing Commission, together with any amendments to such guidelines or policy statements by act of Congress."],[0,"(c) Statement of Reasons for Imposing a Sentence.—The court, at the time of sentencing, shall state in open court the reasons for its imposition of the particular sentence, and, if the sentence—"],[1,"(1) is of the kind, and within the range, described in subsection (a)(4), and that range exceeds 24 months, the reason for imposing a sentence at a particular point within the range; or"],[1,"(2) is not of the kind, or is outside the range, described in subsection (a)(4), the specific reason for the imposition of a sentence different from that described, which reasons must also be stated with specificity in a statement of reasons form issued under section 994(w)(1)(B) of title 28, except to the extent that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32. In the event that the court relies upon statements received in camera in accordance with Federal Rule of Criminal Procedure 32 the court shall state that such statements were so received and that it relied upon the content of such statements."],[0,"If the court does not order restitution, or orders only partial restitution, the court shall include in the statement the reason therefor. The court shall provide a transcription or other appropriate public record of the court's statement of reasons, together with the order of judgment and commitment, to the Probation System and to the Sentencing Commission,,3 and, if the sentence includes a term of imprisonment, to the Bureau of Prisons."],[0,"(d) Presentence Procedure for an Order of Notice.—Prior to imposing an order of notice pursuant to section 3555, the court shall give notice to the defendant and the Government that it is considering imposing such an order. Upon motion of the defendant or the Government, or on its own motion, the court shall—"],[1,"(1) permit the defendant and the Government to submit affidavits and written memoranda addressing matters relevant to the imposition of such an order;"],[1,"(2) afford counsel an opportunity in open court to address orally the appropriateness of the imposition of such an order; and"],[1,"(3) include in its statement of reasons pursuant to subsection (c) specific reasons underlying its determinations regarding the nature of such an order."],[0,"Upon motion of the defendant or the Government, or on its own motion, the court may in its discretion employ any additional procedures that it concludes will not unduly complicate or prolong the sentencing process."],[0,"(e) Limited Authority To Impose a Sentence Below a Statutory Minimum.—Upon motion of the Government, the court shall have the authority to impose a sentence below a level established by statute as a minimum sentence so as to reflect a defendant's substantial assistance in the investigation or prosecution of another person who has committed an offense. Such sentence shall be imposed in accordance with the guidelines and policy statements issued by the Sentencing Commission pursuant to section 994 of title 28, United States Code."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3553?type=usc&year=mostrecent&link-type=html"},"head":"§3553. Imposition of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"11, 12, 14","1":"22, 22, 22, 22"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(f)(1)","(g)"],"stext":{"head":"§3742. Review of a sentence","paras":[[0,"(a) Appeal by a Defendant.—A defendant may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines; or"],[1,"(3) is greater than the sentence specified in the applicable guideline range to the extent that the sentence includes a greater fine or term of imprisonment, probation, or supervised release than the maximum established in the guideline range, or includes a more limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the maximum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"(b) Appeal by the Government.—The Government may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is less than the sentence specified in the applicable guideline range to the extent that the sentence includes a lesser fine or term of imprisonment, probation, or supervised release than the minimum established in the guideline range, or includes a less limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the minimum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"The Government may not further prosecute such appeal without the personal approval of the Attorney General, the Solicitor General, or a deputy solicitor general designated by the Solicitor General."],[0,"(c) Plea Agreements.—In the case of a plea agreement that includes a specific sentence under rule 11(e)(1)(C) of the Federal Rules of Criminal Procedure—"],[1,"(1) a defendant may not file a notice of appeal under paragraph (3) or (4) of subsection (a) unless the sentence imposed is greater than the sentence set forth in such agreement; and"],[1,"(2) the Government may not file a notice of appeal under paragraph (3) or (4) of subsection (b) unless the sentence imposed is less than the sentence set forth in such agreement."],[0,"(d) Record on Review.—If a notice of appeal is filed in the district court pursuant to subsection (a) or (b), the clerk shall certify to the court of appeals—"],[1,"(1) that portion of the record in the case that is designated as pertinent by either of the parties;"],[1,"(2) the presentence report; and"],[1,"(3) the information submitted during the sentencing proceeding."],[0,"(e) Consideration.—Upon review of the record, the court of appeals shall determine whether the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is outside the applicable guideline range, and"],[2,"(A) the district court failed to provide the written statement of reasons required by section 3553(c);"],[2,"(B) the sentence departs from the applicable guideline range based on a factor that—"],[3,"(i) does not advance the objectives set forth in section 3553(a)(2); or"],[3,"(ii) is not authorized under section 3553(b); or"],[3,"(iii) is not justified by the facts of the case; or"],[2,"(C) the sentence departs to an unreasonable degree from the applicable guidelines range, having regard for the factors to be considered in imposing a sentence, as set forth in section 3553(a) of this title and the reasons for the imposition of the particular sentence, as stated by the district court pursuant to the provisions of section 3553(c); or"],[1,"(4) was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable."],[0,"The court of appeals shall give due regard to the opportunity of the district court to judge the credibility of the witnesses, and shall accept the findings of fact of the district court unless they are clearly erroneous and, except with respect to determinations under subsection (3)(A) or (3)(B), shall give due deference to the district court's application of the guidelines to the facts. With respect to determinations under subsection (3)(A) or (3)(B), the court of appeals shall review de novo the district court's application of the guidelines to the facts."],[0,"(f) Decision and Disposition.—If the court of appeals determines that—"],[1,"(1) the sentence was imposed in violation of law or imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings with such instructions as the court considers appropriate;"],[1,"(2) the sentence is outside the applicable guideline range and the district court failed to provide the required statement of reasons in the order of judgment and commitment, or the departure is based on an impermissible factor, or is to an unreasonable degree, or the sentence was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable, it shall state specific reasons for its conclusions and—"],[2,"(A) if it determines that the sentence is too high and the appeal has been filed under subsection (a), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[2,"(B) if it determines that the sentence is too low and the appeal has been filed under subsection (b), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[1,"(3) the sentence is not described in paragraph (1) or (2), it shall affirm the sentence."],[0,"(g) Sentencing Upon Remand.—A district court to which a case is remanded pursuant to subsection (f)(1) or (f)(2) shall resentence a defendant in accordance with section 3553 and with such instructions as may have been given by the court of appeals, except that—"],[1,"(1) In determining the range referred to in subsection 3553(a)(4), the court shall apply the guidelines issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, and that were in effect on the date of the previous sentencing of the defendant prior to the appeal, together with any amendments thereto by any act of Congress that was in effect on such date; and"],[1,"(2) The court shall not impose a sentence outside the applicable guidelines range except upon a ground that—"],[2,"(A) was specifically and affirmatively included in the written statement of reasons required by section 3553(c) in connection with the previous sentencing of the defendant prior to the appeal; and"],[2,"(B) was held by the court of appeals, in remanding the case, to be a permissible ground of departure."],[0,"(h) Application to a Sentence by a Magistrate Judge.—An appeal of an otherwise final sentence imposed by a United States magistrate judge may be taken to a judge of the district court, and this section shall apply (except for the requirement of approval by the Attorney General or the Solicitor General in the case of a Government appeal) as though the appeal were to a court of appeals from a sentence imposed by a district court."],[0,"(i) Guideline Not Expressed as a Range.—For the purpose of this section, the term \"guideline range\" includes a guideline range having the same upper and lower limits."],[0,"(j) Definitions.—For purposes of this section—"],[1,"(1) a factor is a \"permissible\" ground of departure if it—"],[2,"(A) advances the objectives set forth in section 3553(a)(2); and"],[2,"(B) is authorized under section 3553(b); and"],[2,"(C) is justified by the facts of the case; and"],[1,"(2) a factor is an \"impermissible\" ground of departure if it is not a permissible factor within the meaning of subsection (j)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3742?type=usc&year=mostrecent&link-type=html"},"head":"§3742. Review of a sentence","tname":"Crimes and Criminal Procedure","by":{"0":"16","1":"31, 31, 32"}},{"t":"usc","label":"28 U.S.C. § 991","url":"https://www.law.cornell.edu/uscode/text/28/991","subs":["(b)"],"by":{"0":"14"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","by":{"0":"14, 15"}},{"t":"rule","label":"Fed. R. Crim. P. 32","url":"https://www.law.cornell.edu/rules/frcrmp/rule_32","subs":["(c)"],"by":{"0":"12"}},{"t":"rule","label":"Fed. R. Crim. P. 52","url":"https://www.law.cornell.edu/rules/frcrmp/rule_52","subs":["(b)"],"by":{"0":"1, 6"}},{"t":"case","label":"Beckles v. United States","cite":"137 S. Ct. 886","y":2017,"id":"2016/15-8544","sc":1,"sum":"The Court held that its holding in Johnson v. US regarding the unconstitutionality of the residual clause in the Armed Criminal Career Act does not apply retroactively to identical language in the Sentencing Guidelines.","sumSrc":"Oyez","by":{"1":"2, 20"}},{"t":"case","label":"Black v. Cutter Labs.","cite":"351 U.S. 292","y":1956,"id":"1955/92","sc":1,"sum":"The decision involves only California's construction of a local contract under local law; no substantial federal question is presented; and the writ of certiorari is dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 36"}},{"t":"case","label":"Brasfield v. United States","cite":"272 U.S. 448","y":1926,"id":"scdb/1926-005","sc":1,"ar":1,"sum":"1. An inquiry, put by the trial judge to a jury unable to agree, asking the extent of its division numerically, is per se ground for reversal.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19","2":"6"}},{"t":"case","label":"Burns v. United States","cite":"501 U.S. 129","y":1991,"id":"1990/89-7260","sc":1,"sum":"Before a district court can depart upward from the applicable Guidelines range on a ground not identified as a ground for such departure either in the presentence report or in a prehearing submission by the Government, Rule 32 requires that the court give the parties reasonable notice that it is contemplating such a ruling, specifically identifying the ground for the departure.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"ar":2,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Jones v. United States","cite":"527 U.S. 373","y":1999,"id":"1998/97-9361","sc":1,"sum":"The Court held that Jones was not entitled to an instruction as to the effect of jury deadlock. The Court held that the Eighth Amendment does not require such an instruction and the Court declined to exercise its supervisory powers to require such an instruction in every capital case.","sumSrc":"Oyez","by":{"1":"15, 17, 23"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"sum":"The Court held that counsel must inform a client whether or not his plea carries a risk of deportation under the Sixth Amendment.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Peguero v. United States","cite":"526 U.S. 23","y":1999,"id":"1998/97-9217","sc":1,"sum":"The Court held that \"a district court's failure to advise the defendant of his right to appeal does not entitle him to habeas relief if he knew of his right and hence suffered no prejudice from the omission.\" Noting the importance of the rule and acknowledging that the omission was an error, Justice Kennedy stated \"[t]rial judges must be meticulous and precise in following each of the requirements of Rule 32 in every case.\" The Court concluded that Rule 32 violations do not entitle defendants to relief in all circumstances, rather only when the defendant is prejudiced by the court's error.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"ar":1,"sum":"The Court held that when a defendant's sentence has been set aside on appeal, a district court may consider evidence of the defendant's rehabilitation after the initial sentences, which may support lesser sentencing guidelines.","sumSrc":"Oyez","by":{"1":"27, 30, 32, 33"}},{"t":"case","label":"Sibron v. New York","cite":"392 U.S. 40","y":1968,"id":"1967/63","sc":1,"sum":"In an 8-to-1 decision, the Court began by noting that although states may grant police officers great latitude in making arrests, all search and seizures are subject to constitutional limitations. In Sibron's case, the Court noted that officer Martinez never actually heard any of the conversations between Sibron and the narcotics addicts.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"United States v. Alegria-Alvarez","cite":"471 Fed. Appx. 271","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./471/271/","by":{"1":"35"}},{"t":"case","label":"United States v. Andino-Ortega","cite":"608 F.3d 305","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/608/305/","by":{"1":"35"}},{"t":"case","label":"United States v. Atkinson","cite":"297 U.S. 157","y":1936,"id":"scdb/1935-082","sc":1,"ar":2,"sum":"In the absence of exceptional circumstances, error in a jury trial, which was not brought to the attention of the court by proper exception or request to charge, will not be considered on appeal. P. 159. 76 F. (2d) 564, affirmed. CERTIORARI, 296 U. S. 559, to review a judgment affirming a judgment against the United States in an action on a policy of converted war risk insurance. Mr. Will G. Beardslee, with whom …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3, 11, 12, 16, 23"}},{"t":"case","label":"United States v. Barbosa","cite":"698 Fed. Appx. 206","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./698/206/","sum":"Concluding that the “shock the conscience” description is inaccurate.","sumSrc":"brief:1","by":{"1":"35"}},{"t":"case","label":"United States v. Burns","cite":"298 F.3d 523","y":2002,"url":"https://www.courtlistener.com/c/F.3d/298/523/","by":{"1":"25"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"ar":3,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"1":"15, 16, 17, 29, 39"}},{"t":"case","label":"United States v. Dias","cite":"682 Fed. Appx. 292","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./682/292/","by":{"1":"35"}},{"t":"case","label":"United States v. Dominguez Benitez","cite":"542 U.S. 74","y":2004,"id":"2003/03-167","sc":1,"sum":"The Court ruled that the judge's error most likely had no effect on Dominguez's decision to plead guilty, because he had already confessed to the crime and had little chance of winning at trial. Under Rule 52, a plain error is an \"error that affects substantial rights.\" Because the error did not harm Dominguez - he would likely have pled guilty anyway - it was not a reversible plain error.","sumSrc":"Oyez","by":{"1":"10, 14, 17"}},{"t":"case","label":"United States v. Ellis","cite":"326 F.3d 593","y":2003,"url":"https://www.courtlistener.com/c/F.3d/326/593/","ar":3,"by":{"1":"25"}},{"t":"case","label":"United States v. Flores-Mejia","cite":"759 F.3d 253","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/759/253/","by":{"1":"32"}},{"t":"case","label":"United States v. Hernandez","cite":"690 F.3d 613","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/690/613/","by":{"1":"35"}},{"t":"case","label":"United States v. Lewis","cite":"823 F.3d 1075","y":2016,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/823/1075/","by":{"1":"32"}},{"t":"case","label":"United States v. Marcus","cite":"560 U.S. 258","y":2010,"id":"2009/08-1341","sc":1,"sum":"The Court held that an appellate court may correct an error not raised at trial only when the appellant demonstrates that: (1) there is an error; (2) the error is clear and obvious; (3) the error affected the appellant's substantial rights; and (4) the error seriously affects the fairness, integrity, or public reputation of judicial proceedings.","sumSrc":"Oyez","by":{"1":"14, 15"}},{"t":"case","label":"United States v. Marroquin","cite":"874 F.3d 851","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/851/","by":{"1":"35"}},{"t":"case","label":"United States v. Martinez-Rodriguez","cite":"821 F.3d 659","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/659/","by":{"1":"35"}},{"t":"case","label":"United States v. Mendoza-Velasquez","cite":"847 F.3d 209","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/209/","by":{"1":"34"}},{"t":"case","label":"United States v. Miller","cite":"657 Fed. Appx. 265","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./657/265/","by":{"1":"35"}},{"t":"case","label":"United States v. Padilla","cite":"415 F.3d 211","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/415/211/","by":{"1":"32"}},{"t":"case","label":"United States v. Rojas-Ibarra","cite":"669 Fed. Appx. 269","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./669/269/","by":{"1":"35"}},{"t":"case","label":"United States v. Samas","cite":"561 F.3d 108","y":2009,"url":"https://www.courtlistener.com/c/F.3d/561/108/","by":{"1":"25"}},{"t":"case","label":"United States v. Santacruz-Hernandez","cite":"648 Fed. Appx. 456","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./648/456/","by":{"1":"35"}},{"t":"case","label":"United States v. Sarabia-Martinez","cite":"779 F.3d 274","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/779/274/","by":{"1":"9"}},{"t":"case","label":"United States v. Segura","cite":"747 F.3d 323","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/747/323/","by":{"1":"9, 33, 34, 35"}},{"t":"case","label":"United States v. Solano-Hernandez","cite":"847 F.3d 170","y":2017,"court":"filed May 1","url":"https://www.courtlistener.com/c/F.3d/847/170/","by":{"1":"34"}},{"t":"case","label":"United States v. Vonn","cite":"535 U.S. 55","y":2002,"id":"2001/00-973","sc":1,"sum":"The Court held 8-1 that silent defendant has the burden to satisfy the plain-error rule and unanimously that a reviewing court may consult the whole record when considering the effect of any error on substantial rights.","sumSrc":"Oyez","by":{"1":"15, 17, 18, 27, 29"}},{"t":"case","label":"United States v. Young","cite":"470 U.S. 1","y":1985,"id":"1984/83-469","sc":1,"sum":"The prosecutor's remarks during the rebuttal argument, although error, did not constitute \"plain error\" that a reviewing court could properly act on under Federal Rule of Criminal Procedure 52(b), absent a timely objection by defense counsel; on the record, the challenged argument did not undermine the fairness of the trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim"}},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"sum":"Respondent's failure to make timely objection under the Florida contemporaneous-objection rule to the admission of his inculpatory statements, absent a showing of cause for the noncompliance and some showing of actual prejudice, bars federal habeas corpus review of his Miranda claim. Davis v. United States, 411 U. S. 233; Francis v. Henderson,425 U. S. 536.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17, 18"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"1":"13, 28"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"1":"30"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"34"}},{"t":"usc","label":"8 U.S.C. § 1326","url":"https://www.law.cornell.edu/uscode/text/8/1326","subs":["(a)","(b)(2)"],"by":{"1":"2, 4, 36, 2, 4, 36"}},{"t":"usc","label":"18 U.S.C. § 3661","url":"https://www.law.cornell.edu/uscode/text/18/3661","by":{"1":"33"}},{"t":"usc","label":"18 U.S.C. § 3771","url":"https://www.law.cornell.edu/uscode/text/18/3771","subs":["(a)"],"by":{"1":"32"}},{"t":"case","label":"Bracy v. Gramley","cite":"520 U.S. 899","y":1997,"id":"1996/96-6133","sc":1,"sum":"The Court held that Bracy had made a sufficient factual showing to establish \"good cause,\" as required by Habeas Corpus Rule 6(a), for discovery on his claim of actual judicial bias in his case.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Kimmelman v. Morrison","cite":"477 U.S. 365","y":1986,"id":"1985/84-1661","sc":1,"sum":"At respondent's bench trial in a New Jersey court resulting in his conviction of rape, a police officer testified that a few hours after the rape she accompanied the victim to respondent's apartment where the rape had occurred; that he was not there but another tenant let them into respondent's apartment; and that the officer seized a sheet from respondent's bed. At such point in the testimony, respondent's counsel …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10, 11"}},{"t":"case","label":"Koon v. United States","cite":"518 U.S. 81","y":1996,"id":"1995/94-1664","sc":1,"sum":"The Court held that the Court of Appeals should not review de novo a decision to depart from the Guideline sentencing range, but instead should ask whether the sentencing court abused its discretion.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"United States v. Jenkins","cite":"854 F.3d 181","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/854/181/","by":{"2":"5, 6"}},{"t":"case","label":"United States v. Tyson","cite":"863 F.3d 597","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/863/597/","ar":1,"by":{"2":"8"}},{"t":"case","label":"COURT DOCUMENTS Brief of Plaintiff-Appellee, United States v. Fiallos","cite":"2017 WL 6552177","y":2017,"court":"5th Cir. Dec. 13","by":{"2":"3"}},{"t":"case","label":"Appellee’s Brief, United States v. Fuentes","cite":"2017 WL 5759744","y":2017,"court":"5th Cir. Nov. 20","by":{"2":"3"}},{"t":"case","label":"Original Brief of Appellee, United States v. Washington","cite":"2017 WL 4708216","y":2017,"court":"5th Cir. Oct. 12","by":{"2":"3"}}]};